{"hypothesis":"Combining structured reflection-symmetric cold starts with analytic distance constraints and full-coordinate polishing will raise the verified cold-start mean above 2.35.","rationale":"The first parent supplies reliable exact verification and unrestricted polishing, while the second supplies a smaller reflection quotient and active-contact refinement. Starting that quotient from compact staggered lattices avoids spending the short budget expanding the tiny-radius cold inputs.","source":"import time
from fractions import Fraction
import numpy as np
from scipy.optimize import minimize
from scipy.linalg import lstsq

PARAMS = {
    'iterations': (220, 80, 500),
    'polish_fraction': (0.15, 0.05, 0.35),
    'safety': (1e-14, 4e-15, 1e-11, 'log')
}
I, J = np.triu_indices(21, 1)

class Timeout(Exception):
    pass

def valid(a):
    if a.shape != (21, 3) or not np.isfinite(a).all() or np.any(a[:, 2] <= 0):
        return False
    d = np.sqrt((a[I, 0]-a[J, 0])**2 + (a[I, 1]-a[J, 1])**2)
    if np.any(d < a[I, 2]+a[J, 2]):
        return False
    x, y, r = [[Fraction(float(v)) for v in a[:, k]] for k in range(3)]
    return (max(u+v for u,v in zip(x,r))-min(u-v for u,v in zip(x,r)) +
            max(u+v for u,v in zip(y,r))-min(u-v for u,v in zip(y,r))) <= 2

def model(sym):
    n = 34 if sym else 64
    X = np.zeros((21,n)); Y = X.copy(); R = X.copy()
    if sym:
        ids = np.r_[np.arange(12),np.arange(3,12)]
        X[np.arange(21),ids] = 1
        R[np.arange(21),21+ids] = 1
        Y[np.arange(3,12),np.arange(12,21)] = 1
        Y[np.arange(12,21),np.arange(12,21)] = -1
        # Retain exactly one representative of each reflection orbit.
        pairs = [(i,j) for i in range(12) for j in range(i+1,12)]
        pairs += [(i,12+j-3) for i in range(3,12) for j in range(i,12)]
        pi,pj = np.asarray(pairs).T
        wallids = np.arange(12)
        ri = np.arange(21,33)
    else:
        X[np.arange(21),np.arange(21)] = 1
        Y[np.arange(21),21+np.arange(21)] = 1
        R[np.arange(21),42+np.arange(21)] = 1
        pi,pj = I,J
        wallids = np.arange(21)
        ri = np.arange(42,63)
    w = np.zeros(n); w[-1] = 1
    B = np.concatenate((.5*w-X[wallids]-R[wallids],
                        .5*w+X[wallids]-R[wallids],
                        -.5*w-Y[wallids]-R[wallids],
                        -.5*w+Y[wallids]-R[wallids]))
    off = np.r_[np.zeros(2*len(wallids)),np.ones(2*len(wallids))]
    return X,Y,R,X[pi]-X[pj],Y[pi]-Y[pj],R[pi]+R[pj],B,off,-R.sum(axis=0),ri

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + .70*budget_s
    eps = float(params['safety'])
    best = None; score = -float('inf')
    def array(obj):
        if 'circles' in obj:
            return np.asarray(obj['circles'],float).copy()
        return np.asarray(obj['state'],float).reshape(3,21).T.copy()
    try:
        if init is not None:
            a = array(init)
            if valid(a):
                best = init; score = float(np.sum(a[:,2]))
    except (ValueError, TypeError, KeyError):
        pass
    def offer(a):
        nonlocal best,score
        a = np.array(a,dtype=float,copy=True)
        if a.shape != (21,3) or not np.isfinite(a).all() or np.any(a[:,2]<=0):
            return
        d = np.sqrt((a[I,0]-a[J,0])**2+(a[I,1]-a[J,1])**2)
        ratio = min(1.,float(np.min(d/(a[I,2]+a[J,2]))))
        if ratio <= 0:
            return
        a[:,2] *= ratio*(1-eps)
        lo = np.min(a[:,:2]-a[:,2,None],axis=0)
        hi = np.max(a[:,:2]+a[:,2,None],axis=0)
        scale = (2-8*eps)/float(np.sum(hi-lo))
        a[:,:2] = (a[:,:2]-(hi+lo)/2)*scale
        a[:,2] *= scale
        s = float(np.sum(a[:,2]))
        if s > score and valid(a):
            score = s; best = {'state':a.T.reshape(-1).tolist()}
    def encode(a):
        lo = np.min(a[:,:2]-a[:,2,None],axis=0)
        hi = np.max(a[:,:2]+a[:,2,None],axis=0)
        return np.r_[a[:,0]-(lo[0]+hi[0])/2,a[:,1]-(lo[1]+hi[1])/2,a[:,2],hi[0]-lo[0]]
    def unpack(z,m):
        return np.column_stack((m[0]@z,m[1]@z,m[2]@z))
    def optimize(z,m,stop):
        dxm,dym,rsm,B,off,obj,ri = m[3:]
        cache = [None,None,None]
        last = [z.copy()]
        count = [0]
        def calc(q):
            if time.monotonic() >= stop:
                raise Timeout()
            if cache[0] is not None and np.array_equal(q,cache[0]):
                return cache[1],cache[2]
            dx = dxm@q; dy = dym@q
            d = np.maximum(np.sqrt(dx*dx+dy*dy),1e-15)
            c = np.r_[d-rsm@q,B@q+off]
            jac = np.concatenate(((dx/d)[:,None]*dxm+(dy/d)[:,None]*dym-rsm,B))
            cache[:] = [q.copy(),c,jac]
            return c,jac
        def fun(q):
            if time.monotonic() >= stop:
                raise Timeout()
            return float(obj@q),obj
        def callback(q):
            if time.monotonic() >= stop:
                raise Timeout()
            last[0] = q.copy(); count[0] += 1
            if count[0] % 12 == 0:
                offer(unpack(q,m))
        bounds = [(None,None)]*len(z)
        for k in ri:
            if time.monotonic() >= stop:
                return z
            bounds[int(k)] = (1e-7,.6)
        bounds[-1] = (.12,1.88)
        try:
            res = minimize(fun,z,jac=True,method='SLSQP',bounds=bounds,
                constraints={'type':'ineq','fun':lambda q:calc(q)[0],'jac':lambda q:calc(q)[1]},
                callback=callback,options={'maxiter':int(params['iterations']),'ftol':5e-13,'disp':False})
            z = res.x
        except Timeout:
            z = last[0]
        offer(unpack(z,m))
        for _ in range(3):
            if time.monotonic() >= stop-.006:
                break
            try:
                c,jac = calc(z)
            except Timeout:
                break
            active = np.flatnonzero(np.abs(c)<3e-7)
            if len(active)<len(z):
                break
            delta,_,rank,_ = lstsq(jac[active],-c[active],lapack_driver='gelsy',check_finite=False)
            if rank<len(z) or np.max(np.abs(delta))>1e-4:
                break
            z = z+delta
            offer(unpack(z,m))
        return z

    sym = model(True)
    full = model(False)
    families = [(3,4,3,4,3,4),(3,4,5,4,5),(4,5,4,5,3)]
    seeds = []
    for counts in families:
        if time.monotonic() >= deadline-.03:
            break
        singles = []; pairs = []
        for col,n in enumerate(counts):
            if time.monotonic() >= deadline-.03:
                break
            x = np.sqrt(3.)*col
            if n%2:
                singles.append((x,0.,1.))
                levels = range(2,n,2)
            else:
                levels = range(1,n,2)
            for y in levels:
                if time.monotonic() >= deadline-.03:
                    break
                pairs.append((x,float(y),1.))
        if len(singles)!=3 or len(pairs)!=9:
            continue
        a = np.asarray(singles+pairs+[(x,-y,r) for x,y,r in pairs],float)
        lo = np.min(a[:,:2]-a[:,2,None],axis=0)
        hi = np.max(a[:,:2]+a[:,2,None],axis=0)
        a[:,:2] -= (lo+hi)/2
        scale = 2/np.sum(hi-lo)
        a *= scale
        offer(a)
        seeds.append(np.r_[a[:12,0],a[3:12,1],a[:12,2],(hi[0]-lo[0])*scale])
    if best is None:
        a = np.array([[2*(i%3),2*(i//3),1.] for i in range(21)])
        offer(a)
    search_end = deadline-float(params['polish_fraction'])*(.70*budget_s)
    if score > 2.36:
        optimize(encode(array(best)),full,deadline-.008)
        return best
    for index,q in enumerate(seeds):
        now = time.monotonic()
        if now >= search_end-.015:
            break
        stop = now+(search_end-now)/(len(seeds)-index)
        optimize(q,sym,stop)
    if time.monotonic()<deadline-.02:
        optimize(encode(array(best)),full,deadline-.008)
    return best
